const FULLWIDTH_CHAR_RE = /[\u1100-\u115f\u2e80-\ua4cf\uac00-\ud7a3\uf900-\ufaff\ufe10-\ufe19\ufe30-\ufe6f\uff00-\uff60\uffe0-\uffe6]/

export function roundCoord(value) {
  const n = Math.round(Number(value) * 10) / 10
  return Object.is(n, -0) ? 0 : n
}

export function displayWidth(text) {
  let w = 0
  for (const ch of String(text ?? '')) w += FULLWIDTH_CHAR_RE.test(ch) ? 2 : 1
  return w
}

export function truncateLabel(text, maxWidth = 28) {
  const s = String(text ?? '').trim()
  if (displayWidth(s) <= maxWidth) return s
  const budget = Math.max(4, maxWidth - 3)
  let acc = 0, out = ''
  for (const ch of s) {
    const w = FULLWIDTH_CHAR_RE.test(ch) ? 2 : 1
    if (acc + w > budget) break
    out += ch; acc += w
  }
  return `${out}...`
}

export function kahnTopoSort(ids, edgePairs, tieBreakCmp = (a, b) => a.localeCompare(b)) {
  const uniqueIds = [...new Set(ids)], idSet = new Set(uniqueIds)
  const rank = new Map(uniqueIds.map((id) => [id, 0]))
  const indeg = new Map(uniqueIds.map((id) => [id, 0]))
  const adj = new Map(uniqueIds.map((id) => [id, new Set()]))
  for (const [u, v] of edgePairs) {
    if (!idSet.has(u) || !idSet.has(v) || u === v || adj.get(u).has(v)) continue
    adj.get(u).add(v); indeg.set(v, (indeg.get(v) || 0) + 1)
  }
  const visited = new Set(), order = []
  while (visited.size < uniqueIds.length) {
    const ready = uniqueIds.filter((id) => !visited.has(id) && (indeg.get(id) || 0) <= 0).sort(tieBreakCmp)
    const cur = ready.length > 0
      ? ready[0]
      : uniqueIds.filter((id) => !visited.has(id)).sort((a, b) => ((indeg.get(a) || 0) - (indeg.get(b) || 0)) || tieBreakCmp(a, b))[0]
    visited.add(cur); order.push(cur)
    const curRank = rank.get(cur) || 0
    for (const nxt of adj.get(cur) || []) {
      if (visited.has(nxt)) continue
      rank.set(nxt, Math.max(rank.get(nxt) || 0, curRank + 1))
      indeg.set(nxt, Math.max(0, (indeg.get(nxt) || 0) - 1))
    }
  }
  return { rank, order }
}

export function normalizeOrthogonalPoints(rawPts) {
  const pts = []
  for (const p of Array.isArray(rawPts) ? rawPts : []) {
    if (!p || !Number.isFinite(p.x) || !Number.isFinite(p.y)) continue
    const x = roundCoord(p.x), y = roundCoord(p.y), prev = pts[pts.length - 1]
    if (prev && Math.abs(prev.x - x) < 0.5 && Math.abs(prev.y - y) < 0.5) continue
    if (pts.length >= 2) {
      const a = pts[pts.length - 2], b = pts[pts.length - 1]
      if ((Math.abs(a.x - b.x) < 0.5 && Math.abs(b.x - x) < 0.5) || (Math.abs(a.y - b.y) < 0.5 && Math.abs(b.y - y) < 0.5)) {
        pts[pts.length - 1] = { x, y }
        continue
      }
    }
    pts.push({ x, y })
  }
  return pts
}

export function roundedOrthogonalPath(rawPts, radius = 10) {
  const pts = normalizeOrthogonalPoints(rawPts)
  if (pts.length < 2) return pts.length === 1 ? `M ${pts[0].x} ${pts[0].y}` : ''
  const parts = [`M ${pts[0].x} ${pts[0].y}`]
  for (let i = 1; i < pts.length - 1; i += 1) {
    const p0 = pts[i - 1], p1 = pts[i], p2 = pts[i + 1]
    const dx1 = p1.x - p0.x, dy1 = p1.y - p0.y, dx2 = p2.x - p1.x, dy2 = p2.y - p1.y
    const len1 = Math.hypot(dx1, dy1), len2 = Math.hypot(dx2, dy2), cr = Math.min(radius, len1 / 2, len2 / 2)
    if (cr < 1 || len1 < 1 || len2 < 1) { parts.push(`L ${p1.x} ${p1.y}`); continue }
    const q1x = roundCoord(p1.x - (dx1 / len1) * cr), q1y = roundCoord(p1.y - (dy1 / len1) * cr)
    const q2x = roundCoord(p1.x + (dx2 / len2) * cr), q2y = roundCoord(p1.y + (dy2 / len2) * cr)
    parts.push(`L ${q1x} ${q1y} Q ${p1.x} ${p1.y} ${q2x} ${q2y}`)
  }
  const last = pts[pts.length - 1]
  return `${parts.join(' ')} L ${last.x} ${last.y}`
}

export function expandLayoutBounds(nodes, edges, groups = [], pad = 32, minW = 420, minH = 260) {
  const xs = [], ys = []
  for (const item of [...nodes, ...groups]) {
    if (!item) continue
    xs.push(item.x, item.x + item.w); ys.push(item.y, item.y + item.h)
  }
  for (const e of edges) {
    for (const p of e.points || []) {
      if (Number.isFinite(p.x) && Number.isFinite(p.y)) { xs.push(p.x); ys.push(p.y) }
    }
  }
  if (xs.length === 0 || ys.length === 0) return { width: minW, height: minH }
  const dx = Math.min(...xs) < pad ? roundCoord(pad - Math.min(...xs)) : 0
  const dy = Math.min(...ys) < pad ? roundCoord(pad - Math.min(...ys)) : 0
  if (dx > 0 || dy > 0) {
    for (const item of [...nodes, ...groups]) {
      item.x = roundCoord(item.x + dx); item.y = roundCoord(item.y + dy)
      if (Number.isFinite(item.cx)) item.cx = roundCoord(item.x + item.w / 2)
      if (Number.isFinite(item.cy)) item.cy = roundCoord(item.y + item.h / 2)
    }
    for (const e of edges) {
      if (Array.isArray(e.points) && e.points.length > 0) {
        e.points = e.points.map((p) => ({ x: roundCoord(p.x + dx), y: roundCoord(p.y + dy) }))
        e.pathD = roundedOrthogonalPath(e.points, 8)
      }
      if (Number.isFinite(e.labelX)) e.labelX = roundCoord(e.labelX + dx)
      if (Number.isFinite(e.labelY)) e.labelY = roundCoord(e.labelY + dy)
    }
  }
  return { width: Math.max(minW, roundCoord(Math.max(...xs) + dx + pad)), height: Math.max(minH, roundCoord(Math.max(...ys) + dy + pad)) }
}

export function spreadSidePorts(box, side, count, pad = 16) {
  const n = Math.max(1, Math.floor(Number(count) || 1))
  const isHoriz = side === 'top' || side === 'bottom'
  const span = isHoriz ? box.w : box.h
  const fixed = side === 'top' ? box.y : (side === 'bottom' ? box.y + box.h : (side === 'left' ? box.x : box.x + box.w))
  const start = isHoriz ? box.x : box.y
  const effPad = Math.min(Math.max(0, pad), Math.max(0, span / 4))
  const ports = []
  for (let i = 0; i < n; i += 1) {
    const coord = roundCoord(start + (n === 1 ? span / 2 : effPad + ((span - effPad * 2) * i) / (n - 1)))
    ports.push({ x: isHoriz ? coord : roundCoord(fixed), y: isHoriz ? roundCoord(fixed) : coord, side, index: i })
  }
  return ports
}

const getBoxFromMap = (boxMap, id) => (!boxMap ? null : (boxMap instanceof Map ? boxMap.get(id) : boxMap[id]) || null)
const boxCenter = (b) => ({ cx: Number.isFinite(b.cx) ? b.cx : b.x + b.w / 2, cy: Number.isFinite(b.cy) ? b.cy : b.y + b.h / 2 })

function chooseSides(src, dst, edge) {
  const sc = boxCenter(src), dc = boxCenter(dst), dx = dc.cx - sc.cx, dy = dc.cy - sc.cy
  let outSide = edge.outSide || '', inSide = edge.inSide || ''
  if (!outSide || !inSide) {
    if (Math.abs(dx) >= Math.abs(dy)) {
      if (!outSide) outSide = dx >= 0 ? 'right' : 'left'
      if (!inSide) inSide = dx >= 0 ? 'left' : 'right'
    } else {
      if (!outSide) outSide = dy >= 0 ? 'bottom' : 'top'
      if (!inSide) inSide = dy >= 0 ? 'top' : 'bottom'
    }
  }
  return { outSide, inSide }
}

export function bundleSharedTrunk(edges, boxMap, { clearance = 14, pad = 16 } = {}) {
  const assignments = new Map(), outGroups = new Map(), inGroups = new Map(), items = [], trunks = []
  for (let idx = 0; idx < (edges || []).length; idx += 1) {
    const edge = edges[idx], id = String(edge?.id || `${edge?.fromId}->${edge?.toId}#${idx}`)
    const src = getBoxFromMap(boxMap, edge?.fromId), dst = getBoxFromMap(boxMap, edge?.toId)
    if (!src || !dst) continue
    const { outSide, inSide } = chooseSides(src, dst, edge)
    const rec = { id, edge, src, dst, outSide, inSide }
    items.push(rec)
    const ok = `${edge.fromId}|${outSide}`, ik = `${edge.toId}|${inSide}`
    if (!outGroups.has(ok)) outGroups.set(ok, [])
    outGroups.get(ok).push(rec)
    if (!inGroups.has(ik)) inGroups.set(ik, [])
    inGroups.get(ik).push(rec)
  }

  for (const [key, group] of outGroups.entries()) {
    const side = group[0].outSide, isHoriz = side === 'top' || side === 'bottom'
    group.sort((a, b) => {
      const ac = boxCenter(a.dst), bc = boxCenter(b.dst)
      return (isHoriz ? (ac.cx - bc.cx) : (ac.cy - bc.cy)) || a.id.localeCompare(b.id)
    })
    const ports = spreadSidePorts(group[0].src, side, group.length, pad)
    let trunk = null
    if (group.length >= 2) {
      const s = group[0].src
      let rawCoord
      if (side === 'right') {
        const minDstX = Math.min(...group.map((g) => g.dst.x))
        rawCoord = minDstX > s.x + s.w + 4 ? Math.min(s.x + s.w + clearance, (s.x + s.w + minDstX) / 2) : s.x + s.w + clearance
      } else if (side === 'left') {
        const maxDstX = Math.max(...group.map((g) => g.dst.x + g.dst.w))
        rawCoord = maxDstX < s.x - 4 ? Math.max(s.x - clearance, (s.x + maxDstX) / 2) : s.x - clearance
      } else if (side === 'bottom') {
        const minDstY = Math.min(...group.map((g) => g.dst.y))
        rawCoord = minDstY > s.y + s.h + 4 ? Math.min(s.y + s.h + clearance, (s.y + s.h + minDstY) / 2) : s.y + s.h + clearance
      } else {
        const maxDstY = Math.max(...group.map((g) => g.dst.y + g.dst.h))
        rawCoord = maxDstY < s.y - 4 ? Math.max(s.y - clearance, (s.y + maxDstY) / 2) : s.y - clearance
      }
      trunk = { key, axis: isHoriz ? 'y' : 'x', coord: roundCoord(rawCoord), side, groupSize: group.length }
      trunks.push(trunk)
    }
    group.forEach((rec, i) => { rec.srcPort = ports[i]; rec.trunk = trunk })
  }

  for (const group of inGroups.values()) {
    const side = group[0].inSide, isHoriz = side === 'top' || side === 'bottom'
    group.sort((a, b) => {
      const ac = boxCenter(a.src), bc = boxCenter(b.src)
      return (isHoriz ? (ac.cx - bc.cx) : (ac.cy - bc.cy)) || a.id.localeCompare(b.id)
    })
    const ports = spreadSidePorts(group[0].dst, side, group.length, pad)
    group.forEach((rec, i) => { rec.dstPort = ports[i] })
  }
  for (const rec of items) {
    assignments.set(rec.id, { srcPort: rec.srcPort, dstPort: rec.dstPort, outSide: rec.outSide, inSide: rec.inSide, trunk: rec.trunk || null })
  }
  return { assignments, trunks }
}

const isPointInsideBox = (pt, b, eps = 0.5) => pt.x > b.x + eps && pt.x < b.x + b.w - eps && pt.y > b.y + eps && pt.y < b.y + b.h - eps

function isSegmentBlockedByObstacles(x1, y1, x2, y2, boxes, eps = 0.5) {
  const minX = Math.min(x1, x2), maxX = Math.max(x1, x2), minY = Math.min(y1, y2), maxY = Math.max(y1, y2)
  for (const b of boxes) {
    if (Math.abs(y1 - y2) < 0.01) {
      if (y1 > b.y + eps && y1 < b.y + b.h - eps && maxX > b.x + eps && minX < b.x + b.w - eps) return true
    } else if (Math.abs(x1 - x2) < 0.01) {
      if (x1 > b.x + eps && x1 < b.x + b.w - eps && maxY > b.y + eps && minY < b.y + b.h - eps) return true
    }
  }
  return false
}

const sameBox = (a, b) => Boolean(a && b && ((a.id && b.id && a.id === b.id) || (Math.abs(a.x - b.x) < 0.5 && Math.abs(a.y - b.y) < 0.5 && Math.abs(a.w - b.w) < 0.5 && Math.abs(a.h - b.h) < 0.5)))

function computeEscapePoint(port, clearance, otherBoxes) {
  const side = port.side || ''
  if (!side) return { x: roundCoord(port.x), y: roundCoord(port.y) }
  let dist = clearance
  for (const b of otherBoxes) {
    if (side === 'right' && port.y > b.y + 0.5 && port.y < b.y + b.h - 0.5 && b.x >= port.x - 0.5) dist = Math.min(dist, Math.max(4, (b.x - port.x) / 2))
    else if (side === 'left' && port.y > b.y + 0.5 && port.y < b.y + b.h - 0.5 && b.x + b.w <= port.x + 0.5) dist = Math.min(dist, Math.max(4, (port.x - (b.x + b.w)) / 2))
    else if (side === 'bottom' && port.x > b.x + 0.5 && port.x < b.x + b.w - 0.5 && b.y >= port.y - 0.5) dist = Math.min(dist, Math.max(4, (b.y - port.y) / 2))
    else if (side === 'top' && port.x > b.x + 0.5 && port.x < b.x + b.w - 0.5 && b.y + b.h <= port.y + 0.5) dist = Math.min(dist, Math.max(4, (port.y - (b.y + b.h)) / 2))
  }
  if (side === 'right') return { x: roundCoord(port.x + dist), y: roundCoord(port.y) }
  if (side === 'left') return { x: roundCoord(port.x - dist), y: roundCoord(port.y) }
  if (side === 'bottom') return { x: roundCoord(port.x), y: roundCoord(port.y + dist) }
  if (side === 'top') return { x: roundCoord(port.x), y: roundCoord(port.y - dist) }
  return { x: roundCoord(port.x), y: roundCoord(port.y) }
}

function compressAxisCoords(mandatory, optional, maxAxis) {
  const dedup = (vals) => {
    const out = []
    for (const v of vals.filter(Number.isFinite).map(roundCoord).sort((a, b) => a - b)) {
      if (out.length === 0 || Math.abs(v - out[out.length - 1]) >= 0.5) out.push(v)
    }
    return out
  }
  const all = dedup([...mandatory, ...optional])
  if (all.length <= maxAxis) return all
  const mandSet = dedup(mandatory)
  const rest = all.filter((v) => !mandSet.some((m) => Math.abs(m - v) < 0.5))
  const keep = Math.max(0, maxAxis - mandSet.length), picked = []
  if (keep > 0 && rest.length > 0) {
    for (let i = 0; i < keep; i += 1) picked.push(rest[Math.min(rest.length - 1, Math.floor((i * rest.length) / keep))])
  }
  return dedup([...mandSet, ...picked])
}

class MinHeap {
  constructor() { this.items = [] }
  get size() { return this.items.length }
  push(node) {
    this.items.push(node)
    for (let i = this.items.length - 1; i > 0;) {
      const p = (i - 1) >> 1
      if (this.items[p].cost <= this.items[i].cost) break
      ;[this.items[p], this.items[i]] = [this.items[i], this.items[p]]
      i = p
    }
  }
  pop() {
    if (this.items.length === 0) return null
    const top = this.items[0], last = this.items.pop()
    if (this.items.length > 0) {
      this.items[0] = last
      for (let i = 0, len = this.items.length; ;) {
        const l = i * 2 + 1, r = l + 1
        let best = i
        if (l < len && this.items[l].cost < this.items[best].cost) best = l
        if (r < len && this.items[r].cost < this.items[best].cost) best = r
        if (best === i) break
        ;[this.items[i], this.items[best]] = [this.items[best], this.items[i]]
        i = best
      }
    }
    return top
  }
}

function measurePath(pts) {
  let length = 0
  for (let i = 1; i < pts.length; i += 1) length += Math.abs(pts[i].x - pts[i - 1].x) + Math.abs(pts[i].y - pts[i - 1].y)
  return { bends: Math.max(0, pts.length - 2), length: roundCoord(length) }
}

function buildFallbackEnvelopeRoute(srcPort, dstPort, allBoxes, clearance, radius) {
  const ys = [srcPort.y, dstPort.y, ...allBoxes.flatMap((b) => [b.y, b.y + b.h])]
  const topY = Math.max(8, roundCoord(Math.min(...ys) - clearance)), botY = roundCoord(Math.max(...ys) + clearance)
  const railY = Math.abs(srcPort.y - topY) + Math.abs(dstPort.y - topY) <= Math.abs(srcPort.y - botY) + Math.abs(dstPort.y - botY) ? topY : botY
  const pts = normalizeOrthogonalPoints([srcPort, { x: srcPort.x, y: railY }, { x: dstPort.x, y: railY }, dstPort])
  const { bends, length } = measurePath(pts)
  return { points: pts, pathD: roundedOrthogonalPath(pts, radius), routedFallback: true, bends, length }
}

export function routeOrthogonalObstacleGrid(srcPort, dstPort, obstacles = [], {
  clearance = 14,
  bendPenalty = 18,
  maxGridAxis = 64,
  srcBox = null,
  dstBox = null,
  trunk = null,
  radius = 10,
} = {}) {
  const sPort = { x: roundCoord(srcPort.x), y: roundCoord(srcPort.y), side: srcPort.side || '' }
  const dPort = { x: roundCoord(dstPort.x), y: roundCoord(dstPort.y), side: dstPort.side || '' }
  const allBoxes = (obstacles || []).filter((b) => b && !b.isContainer && Number.isFinite(b.x) && Number.isFinite(b.y) && b.w > 0 && b.h > 0)
  const otherBoxes = allBoxes.filter((b) => !sameBox(b, srcBox) && !sameBox(b, dstBox))

  if (otherBoxes.some((b) => isPointInsideBox(sPort, b) || isPointInsideBox(dPort, b))) {
    return buildFallbackEnvelopeRoute(sPort, dPort, allBoxes, clearance, radius)
  }
  const sEsc = computeEscapePoint(sPort, clearance, otherBoxes)
  const dEsc = computeEscapePoint(dPort, clearance, otherBoxes)
  if (allBoxes.some((b) => isPointInsideBox(sEsc, b) || isPointInsideBox(dEsc, b))
    || isSegmentBlockedByObstacles(sPort.x, sPort.y, sEsc.x, sEsc.y, otherBoxes)
    || isSegmentBlockedByObstacles(dEsc.x, dEsc.y, dPort.x, dPort.y, otherBoxes)) {
    return buildFallbackEnvelopeRoute(sPort, dPort, allBoxes, clearance, radius)
  }

  const allX = [sPort.x, dPort.x, sEsc.x, dEsc.x, ...allBoxes.flatMap((b) => [b.x, b.x + b.w])]
  const allY = [sPort.y, dPort.y, sEsc.y, dEsc.y, ...allBoxes.flatMap((b) => [b.y, b.y + b.h])]
  const mandX = [sPort.x, dPort.x, sEsc.x, dEsc.x, (sEsc.x + dEsc.x) / 2, Math.max(8, Math.min(...allX) - clearance), Math.max(...allX) + clearance]
  const mandY = [sPort.y, dPort.y, sEsc.y, dEsc.y, (sEsc.y + dEsc.y) / 2, Math.max(8, Math.min(...allY) - clearance), Math.max(...allY) + clearance]
  if (trunk && Number.isFinite(trunk.coord)) (trunk.axis === 'x' ? mandX : mandY).push(trunk.coord)
  const optX = [], optY = []
  for (const b of allBoxes) {
    optX.push(Math.max(8, b.x - clearance), b.x + b.w + clearance)
    optY.push(Math.max(8, b.y - clearance), b.y + b.h + clearance)
  }

  const xs = compressAxisCoords(mandX, optX, maxGridAxis), ys = compressAxisCoords(mandY, optY, maxGridAxis)
  const nx = xs.length, ny = ys.length
  const findIdx = (arr, target) => arr.reduce((best, v, i) => (Math.abs(v - target) < Math.abs(arr[best] - target) ? i : best), 0)
  const sx = findIdx(xs, sEsc.x), sy = findIdx(ys, sEsc.y), tx = findIdx(xs, dEsc.x), ty = findIdx(ys, dEsc.y)

  const dist = new Float64Array(nx * ny * 3).fill(Infinity)
  const prev = new Int32Array(nx * ny * 3).fill(-1)
  const stateId = (ix, iy, dir) => ((iy * nx + ix) * 3) + dir
  const startDir = sPort.side === 'left' || sPort.side === 'right' ? 0 : (sPort.side === 'top' || sPort.side === 'bottom' ? 1 : 2)
  const startState = stateId(sx, sy, startDir)
  dist[startState] = 0
  const heap = new MinHeap()
  heap.push({ state: startState, cost: 0 })

  const DIRS = [[1, 0, 0], [-1, 0, 0], [0, 1, 1], [0, -1, 1]]
  let goalState = -1
  while (heap.size > 0) {
    const cur = heap.pop()
    if (cur.cost > dist[cur.state]) continue
    const dir = cur.state % 3, cell = (cur.state - dir) / 3, ix = cell % nx, iy = (cell - ix) / nx
    if (ix === tx && iy === ty) { goalState = cur.state; break }
    const x1 = xs[ix], y1 = ys[iy]
    for (const [dx, dy, ndir] of DIRS) {
      const nix = ix + dx, niy = iy + dy
      if (nix < 0 || nix >= nx || niy < 0 || niy >= ny) continue
      const x2 = xs[nix], y2 = ys[niy]
      if (isSegmentBlockedByObstacles(x1, y1, x2, y2, allBoxes)) continue
      const segLen = Math.abs(x2 - x1) + Math.abs(y2 - y1)
      const turnCost = dir !== 2 && dir !== ndir ? bendPenalty : 0
      const trunkBonus = trunk && ((trunk.axis === 'x' && ndir === 1 && Math.abs(x2 - trunk.coord) < 0.6)
        || (trunk.axis === 'y' && ndir === 0 && Math.abs(y2 - trunk.coord) < 0.6))
        ? -Math.min(4, segLen * 0.05) : 0
      const nextCost = cur.cost + Math.max(0.1, segLen + turnCost + trunkBonus)
      const ns = stateId(nix, niy, ndir)
      if (nextCost < dist[ns]) { dist[ns] = nextCost; prev[ns] = cur.state; heap.push({ state: ns, cost: nextCost }) }
    }
  }
  if (goalState < 0) return buildFallbackEnvelopeRoute(sPort, dPort, allBoxes, clearance, radius)

  const gridPts = []
  for (let walk = goalState; walk >= 0; walk = prev[walk]) {
    const cell = (walk - (walk % 3)) / 3, ix = cell % nx, iy = (cell - ix) / nx
    gridPts.push({ x: xs[ix], y: ys[iy] })
  }
  gridPts.reverse()
  const pts = normalizeOrthogonalPoints([sPort, ...gridPts, dPort])
  const { bends, length } = measurePath(pts)
  return { points: pts, pathD: roundedOrthogonalPath(pts, radius), routedFallback: false, bends, length }
}

export function routeEdgesOrthogonal(edges, boxMap, obstacles, {
  clearance = 12, pad = 14, bendPenalty = 18, maxGridAxis = 64, radius = 10,
} = {}) {
  const bundled = bundleSharedTrunk(edges, boxMap, { clearance, pad })
  const routed = []
  for (let idx = 0; idx < (edges || []).length; idx += 1) {
    const edge = edges[idx], id = String(edge?.id || `${edge?.fromId}->${edge?.toId}#${idx}`)
    const assign = bundled.assignments.get(id)
    if (!assign) continue
    const res = routeOrthogonalObstacleGrid(assign.srcPort, assign.dstPort, obstacles, {
      clearance, bendPenalty, maxGridAxis,
      srcBox: getBoxFromMap(boxMap, edge.fromId), dstBox: getBoxFromMap(boxMap, edge.toId),
      trunk: assign.trunk, radius,
    })
    routed.push({ ...edge, id, srcPort: assign.srcPort, dstPort: assign.dstPort, trunk: assign.trunk, points: res.points, pathD: res.pathD, routedFallback: res.routedFallback, bends: res.bends })
  }
  return { edges: routed, trunks: bundled.trunks }
}
